from adminhub import db, users, api, audit
from tests.conftest import SAMPLE_USERS
def fresh():
    c=db.connect(":memory:")
    for e,n,r,t in SAMPLE_USERS: users.create_user(c,e,n,r,t)
    return c
c=fresh()
print("pages per_page=2:", api.list_users(c,{"per_page":"2"})["body"]["pages"])
print("pages per_page=10:", api.list_users(c,{"per_page":"10"})["body"]["pages"])
print("page=0:", [u["id"] for u in api.list_users(c,{"page":"0","per_page":"2"})["body"]["users"]])
print("per_page=-1 len:", len(api.list_users(c,{"per_page":"-1"})["body"]["users"]))
for p in [{"per_page":"0"},{"page":"x"}]:
    try: print(api.list_users(c,p))
    except Exception as e: print(p, type(e).__name__, e)
print("inject:", [u["email"] for u in api.search(c,{"q":"zzz%' OR 1=1 --"})["body"]["users"]])
print("quote:", end=" ")
try: print(api.search(c,{"q":"O'Brien"}))
except Exception as e: print(type(e).__name__, e)
print("wildcard _:", [u["email"] for u in api.search(c,{"q":"_"})["body"]["users"]])
print("unknown ids:", api.bulk_deactivate(c,{"ids":["2","99"],"actor":"root"}), c.execute("select target_id from audit_log").fetchall() and [tuple(r) for r in c.execute("select target_id from audit_log")])
try: print(api.bulk_deactivate(c,{"ids":["3"]}))
except Exception as e: print("no actor:", type(e).__name__, e)
try: print(api.bulk_deactivate(c,{"ids":["x"],"actor":"r"}))
except Exception as e: print("bad id:", type(e).__name__, e)
c=fresh(); c.execute("drop table audit_log")
print("audit table missing:", api.bulk_deactivate(c,{"ids":["1"],"actor":"root"}))
EOF
cd / && git -C C:/Users/Jonas/AppData/Local/Temp/cc-agentic-526h398l/repo worktree remove --force "$W/wt"

